import {config,disclosure,methodology} from '../config/commission-config.js';
import {calculate,compare} from './calculator-engine.js';
export function report(s,c=config){const v=calculate(s,c);return {program:c.programName,verification:c.verificationStatus,version:c.version,currency:c.currency,assumptions:s,results:v,scenarios:compare(s,c).map(x=>({name:x.name,monthly:x.current.gross,firstYear:x.firstYear,threeYear:x.threeYear})),methodology,disclosure};}
const csvCell=v=>'"'+String(v).replaceAll('"','""')+'"';
export function csv(s,c=config){const r=report(s,c);const lines=[['Program',r.program],['Verification',r.verification],['Config version',r.version],['Currency',r.currency],['Assumptions',JSON.stringify(r.assumptions)],['Monthly gross',r.results.current.gross],['Annualized gross',r.results.annualized],['First year',r.results.firstYear],['36 months',r.results.threeYear],['Product','Allocation %','Method','Rate or fixed fee','Gross commission'],...r.results.current.items.map(x=>[x.name,s.allocation[x.id],x.method,x.rate,x.commission]),['Scenario','Monthly','First year','36 months'],...r.scenarios.map(x=>[x.name,x.monthly,x.firstYear,x.threeYear]),['Month','Modeled deals','Funded volume','Gross earned','Receipts','Expenses','Pre-tax operating income','Cumulative gross'],...r.results.rows.slice(0,s.horizon).map(x=>[x.month,x.deals,x.volume,x.gross,x.receipts,x.expense,x.operatingIncome,x.cumulative]),['Methodology',r.methodology],['Disclosure',r.disclosure]];return lines.map(row=>row.map(csvCell).join(',')).join('\r\n');}
export function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function shareUrl(s,href=location.href){const u=new URL(href);u.search='';u.hash='';u.searchParams.set('s',JSON.stringify(s));return u.href;}
